// studio_off_scan.ino — ESP32-S3: рассылка OFF по всем IP 192.168.0.1–192.168.4.254
#include <WiFi.h>
#include <WiFiUdp.h>

const char* WIFI_SSIDS[] = { "DIR-615T-0DBC", "KIBERone", "KIBERone5" };
const char* WIFI_PASSS[] = { "23233010", "KIBERone", "KIBERone" };
const int   NET_COUNT = 3;

const int UDP_PORT = 8085;
const int BUTTON   = 4;      // кнопка между GPIO4 и GND (внутренняя подтяжка)
const int WAIT_MS  = 15000;

const int FIRST_SUBNET = 0;  // 192.168.0.x
const int LAST_SUBNET  = 4;  // 192.168.4.x

WiFiUDP udp;

bool connectTo(int idx) {
  WiFi.mode(WIFI_STA);
  WiFi.disconnect(false);
  WiFi.begin(WIFI_SSIDS[idx], WIFI_PASSS[idx]);
  for (int t = 0; t < WAIT_MS / 500; t++) {
    if (WiFi.status() == WL_CONNECTED) return true;
    delay(500);
  }
  return false;
}

void blastRange() {
  // два прохода — UDP иногда теряется
  for (int pass = 0; pass < 2; pass++) {
    for (int sub = FIRST_SUBNET; sub <= LAST_SUBNET; sub++) {
      for (int host = 1; host <= 254; host++) {
        udp.beginPacket(IPAddress(192, 168, sub, host), UDP_PORT);
        udp.print("OFF");
        udp.endPacket();
        delay(5); // пауза, чтобы не завалить сеть
      }
    }
  }
}

void setup() {
  pinMode(BUTTON, INPUT_PULLUP);
  udp.begin(UDP_PORT);
  connectTo(0);
}

void loop() {
  if (digitalRead(BUTTON) == LOW) {
    delay(80); // отсечка помех
    if (digitalRead(BUTTON) == LOW) {
      for (int i = 0; i < NET_COUNT; i++) {
        if (connectTo(i)) blastRange();
      }
      connectTo(0); // вернуться на основную сеть
      while (digitalRead(BUTTON) == LOW) delay(10);
    }
  }
  if (WiFi.status() != WL_CONNECTED) connectTo(0);
  delay(10);
}
